sys_script_include.script:
var HoursRollupService = Class.create();
HoursRollupService.prototype = {
    initialize: function() {},

    recalcEWTPlannedHours: function(ewtSysId) {
        if (!ewtSysId) return;

        var totalPlanned = 0;
        var tcGR = new GlideRecord('x_2316178_contin_0_time_card');
        tcGR.addQuery('employee_work_time', ewtSysId);
        tcGR.addQuery('report_type', 'work');
        tcGR.query();
        while (tcGR.next()) {
            var days = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
            for (var i = 0; i < days.length; i++) {
                totalPlanned += parseFloat(tcGR.getValue(days[i]) || '0');
            }
        }

        var ewt = new GlideRecord('x_2316178_contin_0_ewt');
        if (ewt.get(ewtSysId)) {
            ewt.setValue('planned_hours', totalPlanned);
            ewt.setWorkflow(false);
            ewt.update();

            var rpId = ewt.getValue('resource_plan');
            if (rpId) {
                this.recalcRPPlannedHours(rpId);
            }
        }
    },

    recalcRPPlannedHours: function(rpSysId) {
        if (!rpSysId) return;

        var ga = new GlideAggregate('x_2316178_contin_0_ewt');
        ga.addQuery('resource_plan', rpSysId);
        ga.addAggregate('SUM', 'planned_hours');
        ga.query();
        var totalPlanned = 0;
        if (ga.next()) {
            totalPlanned = parseFloat(ga.getAggregate('SUM', 'planned_hours')) || 0;
        }

        var rp = new GlideRecord('x_2316178_contin_0_res_plan');
        if (rp.get(rpSysId)) {
            rp.setValue('planned_hours', totalPlanned);
            rp.setWorkflow(false);
            rp.update();
        }
    },

    recalcRPActualHours: function(rpSysId) {
        if (!rpSysId) return;

        var ga = new GlideAggregate('x_2316178_contin_0_ewt');
        ga.addQuery('resource_plan', rpSysId);
        ga.addAggregate('SUM', 'actual_hours');
        ga.query();
        var totalActual = 0;
        if (ga.next()) {
            totalActual = parseFloat(ga.getAggregate('SUM', 'actual_hours')) || 0;
        }

        var rp = new GlideRecord('x_2316178_contin_0_res_plan');
        if (rp.get(rpSysId)) {
            rp.setValue('actual_hours', totalActual);
            rp.setWorkflow(false);
            rp.update();
        }
    },

    type: 'HoursRollupService'
};
